-- Resolve the PL/pgSQL variable/column ambiguity discovered by linked staging lint.
create or replace function public.update_graded_egg_sale(target_sale uuid,customer_id uuid,items jsonb,discount numeric,notes text default null,credit_days integer default null)returns public.sales language plpgsql security definer set search_path='' as $$
declare s public.sales;farm_crate_size integer;computed_subtotal numeric:=0;computed_total numeric;active_paid numeric;r public.sales;i record;g public.egg_grades;new_credit integer;new_due date;
begin select*into s from public.sales where id=target_sale for update;if s.id is null or s.status<>'completed'or not public.has_farm_role(s.farm_id,array['admin','manager'])then raise exception'Sale edit denied'using errcode='42501';end if;perform pg_advisory_xact_lock(hashtextextended(s.farm_id::text,0));select f.crate_size into farm_crate_size from public.farms f where f.id=s.farm_id;if customer_id is not null and not exists(select 1 from public.customers c where c.id=customer_id and c.farm_id=s.farm_id and c.active)then raise exception'Invalid customer'using errcode='42501';end if;
 for i in select (x->>'egg_grade_id')::uuid grade_id,x->>'unit'unit,(x->>'quantity')::integer qty,(x->>'price_per_unit')::numeric price from jsonb_array_elements(items)x loop select*into g from public.egg_grades where id=i.grade_id and farm_id=s.farm_id and is_active and not is_unsorted;if g.id is null or i.unit not in('crate','loose_egg')or i.qty<=0 or i.price<0 then raise exception'Invalid graded sale item'using errcode='23514';end if;computed_subtotal:=computed_subtotal+round(i.qty*i.price,2);end loop;computed_total:=round(computed_subtotal,2)-discount;select coalesce(sum(amount),0)into active_paid from public.customer_payments where sale_id=s.id and voided_at is null;if computed_total<active_paid or discount<0 or discount>computed_subtotal then raise exception'Invalid sale edit or total below active payments'using errcode='23514';end if;new_credit:=coalesce(credit_days,s.credit_days);if computed_total>active_paid and(new_credit is null or new_credit not between 1 and 365)then raise exception'Credit terms are required for unpaid or partially paid sales'using errcode='23514';end if;if new_credit is not null then new_due:=s.sale_date+new_credit;end if;
 delete from public.sale_items where sale_id=s.id;delete from public.egg_inventory_movements where source_type='egg_sale'and source_id=s.id and movement_type='sale';for i in select (x->>'egg_grade_id')::uuid grade_id,x->>'unit'unit,(x->>'quantity')::integer qty,(x->>'price_per_unit')::numeric price from jsonb_array_elements(items)x loop select*into g from public.egg_grades where id=i.grade_id;insert into public.sale_items(sale_id,egg_grade_id,egg_grade_code_snapshot,egg_grade_name_snapshot,item_type,quantity,eggs_per_unit,price_per_unit,total_eggs,line_total)values(s.id,g.id,g.system_code,g.name,i.unit,i.qty,case when i.unit='crate'then farm_crate_size else 1 end,i.price,i.qty*case when i.unit='crate'then farm_crate_size else 1 end,round(i.qty*i.price,2));insert into public.egg_inventory_movements(farm_id,egg_grade_id,movement_date,movement_type,direction,quantity_eggs,source_type,source_id,created_by)values(s.farm_id,g.id,s.sale_date,'sale','OUT',i.qty*case when i.unit='crate'then farm_crate_size else 1 end,'egg_sale',s.id,auth.uid())on conflict(source_type,source_id,movement_type,egg_grade_id)where source_id is not null do update set quantity_eggs=public.egg_inventory_movements.quantity_eggs+excluded.quantity_eggs;perform public.assert_nonnegative_egg_grade_history(s.farm_id,g.id);end loop;update public.sales set customer_id=$2,subtotal=round(computed_subtotal,2),discount=$4,total_amount=computed_total,notes=nullif(trim($5),''),credit_days=new_credit,payment_due_date=new_due,updated_by=auth.uid()where id=s.id returning*into r;return r;end;$$;
